  'sg.renovation': ['Renovation?', 'Ubah suai?', '装修造成？'], 'sg.warranty': ['Warranty?', 'Waranti?', '保修？'],
  'sg.inspect': ['Inspect', 'Periksa', '待检查'], 'sg.no_change': ['No change', 'Tiada perubahan', '没有变化'], 'sg.retake': ['Retake', 'Ambil semula', '重拍'],
