  'tk.open': ['With SDP', 'Dengan SDP', 'SDP 处理中'], 'tk.repair_submitted': ['Confirm', 'Sahkan', '待你确认'], 'tk.closed': ['Closed', 'Ditutup', '已关闭'],

  'hint.renovation': ['Appeared after work began next door: both owners look at it together first', 'Muncul selepas kerja bermula di sebelah: kedua-dua pemilik semak bersama dahulu', '在隔壁开工后出现：先由双方屋主一起看看'],
  'hint.warranty': ['Possible building defect: refer to SDP warranty with these photos', 'Mungkin kecacatan bangunan: rujuk kepada waranti SDP dengan foto ini', '可能是建筑瑕疵：用这些照片向 SDP 申请保修'],
  'hint.inspect': ['Not clear: ask an SDP inspector to look', 'Tidak jelas: minta pemeriksa SDP melihat', '无法判断：请 SDP 检查员来看'],
  'hint.no_change': ['No visible change found between the photos', 'Tiada perubahan ketara antara kedua-dua foto', '两张照片之间看不出变化'],
  'hint.retake': ['Photos could not be matched: retake from the same spot', 'Foto tidak dapat dipadankan: ambil semula dari tempat yang sama', '照片对不上：请在同一个位置重拍'],
  'why.retake_unaligned': ['The two photos could not be lined up.', 'Kedua-dua foto tidak dapat diselaraskan.', '两张照片对不齐。'],
  'why.retake_tip': ['Stand where you took the first photo and include a fixed feature: a corner, socket or window frame.', 'Berdiri di tempat foto pertama diambil dan masukkan ciri tetap: bucu, soket atau bingkai tingkap.', '站在拍第一张照片的位置，拍进固定的东西：墙角、插座或窗框。'],
  'why.no_change_none': ['No new crack, stain or mark was flagged.', 'Tiada retak, kesan air atau tanda baharu dikesan.', '没有发现新的裂缝、水渍或痕迹。'],
  'why.no_change_tip': ['If you can still see damage, retake the photo closer and from the same angle.', 'Jika anda masih nampak kerosakan, ambil semula foto lebih dekat dari sudut yang sama.', '如果你还是看得到损坏，请从同一个角度靠近一点重拍。'],
  'why.change_found': ['A new {found} appeared in the same spot.', '{found} baharu muncul di tempat yang sama.', '同一个位置出现了新的{found}。'],
  'why.no_renovation': ['No renovation is registered in your neighbour circle.', 'Tiada ubah suai didaftarkan dalam lingkungan jiran anda.', '你的邻里圈没有登记装修。'],
  'why.maybe_defect': ['This may be a building defect: the photos can go straight into the SDP warranty claim.', 'Ini mungkin kecacatan bangunan: foto ini boleh terus digunakan untuk tuntutan waranti SDP.', '这可能是建筑瑕疵：照片可以直接用来向 SDP 申请保修。'],
  'why.seen_before_work': ['The change was photographed on {seen}, before work started at {label} ({start}), so the renovation cannot have caused it.', 'Perubahan ini difoto pada {seen}, sebelum kerja bermula di {label} ({start}), jadi ia tidak mungkin disebabkan oleh ubah suai.', '这个变化是在 {seen} 拍到的，比 {label} 开工（{start}）还早，所以不可能是装修造成的。'],
  'why.photo_before_work': ['Your pre-work photo was taken on {taken}, before work started at {label} ({start}).', 'Foto sebelum kerja anda diambil pada {taken}, sebelum kerja bermula di {label} ({start}).', '你的开工前照片是 {taken} 拍的，在 {label} 开工（{start}）之前。'],
  'why.seen_after_work': ['A new {found} was photographed in the same spot on {seen}, after work began.', '{found} baharu difoto di tempat yang sama pada {seen}, selepas kerja bermula.', '{seen} 在同一个位置拍到新的{found}，那时已经开工。'],
  'why.work_scope': ['Work at {label}: {scope}.', 'Kerja di {label}: {scope}.', '{label} 的工程：{scope}。'],
  'why.timing_not_proof': ["Timing alone does not prove the cause: new homes also crack as they settle. If you can't agree, ask an SDP inspector.", 'Masa sahaja tidak membuktikan punca: rumah baharu juga boleh retak semasa mendap. Jika tidak bersetuju, minta pemeriksa SDP.', '时间先后不能证明原因：新房子沉降时本来也会出现裂缝。如果谈不拢，请 SDP 检查员来看。'],
  'why.photo_after_start': ['But the pre-work photo was taken on {taken}, after work at {label} began ({start}).', 'Tetapi foto sebelum kerja diambil pada {taken}, selepas kerja di {label} bermula ({start}).', '但开工前照片是 {taken} 才拍的，那时 {label} 已经开工（{start}）。'],
