const LOCALE: Record<Lang, string> = { en: 'en-MY', ms: 'ms-MY', zh: 'zh-CN', ta: 'ta-MY' }

/** Dates in the reader's language: "7 Oct 2026", "7 Okt 2026", "2026年10月7日". */
export function useDates() {
  const { lang } = useContext(LangContext)
  return useMemo(() => {
    const loc = LOCALE[lang]
    const date = (iso: string) => new Date(iso).toLocaleDateString(loc, { day: 'numeric', month: 'short', year: 'numeric' })
    const dayMonth = (iso: string) => new Date(iso).toLocaleDateString(loc, { day: 'numeric', month: 'short' })
    return {
      date,
      range: (start: string, end: string) => `${dayMonth(start)} – ${dayMonth(end)}`,
      weekday: (d: Date) => d.toLocaleDateString(loc, { weekday: 'short', day: 'numeric', month: 'short' }),
      time: (d: Date) => d.toLocaleTimeString(loc, { hour: '2-digit', minute: '2-digit' }),
    }
  }, [lang])
}

/** When noisy work is allowed, built from the renovation's own fields in the reader's language. (The English
 *  noisy_hours string stored with the notice stays as the record.) */
export function noisyHours(t: Translate, r: {
  noisy_from?: string | null; noisy_to?: string | null; weekdays_only?: boolean | null; quiet_breaks?: { start: string; end: string }[]
}): string {
  const hours = t(r.weekdays_only === false ? 'hours.monSat' : 'hours.weekdays', { from: r.noisy_from ?? '09:00', to: r.noisy_to ?? '17:00' })
  // Quiet breaks planned around neighbours, e.g. "Weekdays 11:00–17:00, no weekends, quiet 13:00–15:00".
  const sep = t('hours.sep')
  return hours + (r.quiet_breaks ?? []).map((b) => sep + t('hours.quiet', { from: b.start, to: b.end })).join('')
}

/** A date in a given language, outside React (message templates, printed notices). */
export function dateIn(lang: Lang, iso: string): string {
  return new Date(iso).toLocaleDateString(LOCALE[lang], { day: 'numeric', month: 'short', year: 'numeric' })
}

/** A photo subject written by the server ("Shared wall with No. 12") in the reader's language. */
const SUBJECTS: [RegExp, string][] = [
  [/^Shared wall with (.+)$/, 'subj.wall'], [/^Ceiling, two floors below (.+)$/, 'subj.ceiling2'], [/^Ceiling below (.+)$/, 'subj.ceiling'],
  [/^Floor, two floors above (.+)$/, 'subj.floor2'], [/^Floor above (.+)$/, 'subj.floor'], [/^Front of your home facing (.+)$/, 'subj.front'],
]
export function subjectText(t: Translate, subject: string): string {
  for (const [re, key] of SUBJECTS) {
    const m = re.exec(subject)
    if (m) return t(key, { label: m[1] })
  }
  return subject  // typed by a person: shown as written
}

export type Translate = (key: string, vars?: Record<string, string | number>) => string

const IDX: Record<UiLang, number> = { en: 0, ms: 1, zh: 2 }

function translate(lang: Lang, key: string, vars?: Record<string, string | number>): string {
  const entry = D[key]
  let text = lang === 'ta' ? TA[key] ?? entry?.[0] ?? key : entry ? entry[IDX[lang]] || entry[0] : key
  if (vars) {
    // English "home(s)" reads as "home" or "homes", decided by the nearest count before it: "1 home", "5 homes".
    text = text.replace(/\{(\w+)\}([^{}]*?\w)\(s\)/g, (_, k: string, before: string) => `{${k}}${before}${Number(vars[k]) === 1 ? '' : 's'}`)
    for (const [k, v] of Object.entries(vars)) text = text.split(`{${k}}`).join(String(v))
  }
  return text
}

/** A refusal the server explains with a code (tone, private, official), shown in the reader's language. */
export function refusal(e: unknown): string | null {
  return e instanceof ApiError && (e.code === 'tone' || e.code === 'private' || e.code === 'official') ? e.code : null
}

/** A translator fixed to one language, e.g. a printed notice in the recipient's language. */
export const tIn = (lang: Lang): Translate => (k, v) => translate(lang, k, v)

/** English only: for the records screens and the SDP side, whatever the interface language. */
export const tEn: Translate = (k, v) => translate('en', k, v)

/** "Adam (child)" from the server, with the relationship in the reader's language. */
export function byWho(t: Translate, who: string): string {
  const m = /^(.*) \((child|spouse|sibling|caregiver|other)\)$/.exec(who)
  return m ? `${m[1]} (${t(`relation.${m[2]}`)})` : who
}

const LangContext = createContext<{ lang: UiLang; setLang: (l: UiLang) => void; t: Translate }>({
  lang: 'en', setLang: () => {}, t: (k, v) => translate('en', k, v),
})

function initial(): UiLang {
  const v = remembered('uiLang')
  return v === 'ms' || v === 'zh' ? v : 'en'
}

/** Pilot: until someone on this phone picks a language, the app speaks the one the household chose at joining. */
export function langChosen(): boolean {
  return remembered('uiLang') !== null
}

export function LangProvider({ children }: { children: ReactNode }) {
  const [lang, set] = useState<UiLang>(initial)
  const setLang = useCallback((l: UiLang) => {
    set(l)
    remember('uiLang', l)
  }, [])
  const t = useCallback<Translate>((k, v) => translate(lang, k, v), [lang])
  return <LangContext.Provider value={{ lang, setLang, t }}>{children}</LangContext.Provider>
}

/** SDP-side screens that reuse a resident component (e.g. the renovation form at the front desk) stay in English. */
export function EnglishOnly({ children }: { children: ReactNode }) {
  const value = useMemo(() => ({ lang: 'en' as UiLang, setLang: () => {}, t: tEn }), [])
  return <LangContext.Provider value={value}>{children}</LangContext.Provider>
}

export const useLang = () => useContext(LangContext)
export const useT = () => useContext(LangContext).t
